CREATE TABLE IF NOT EXISTS gis_phase368_hierarchy_resolution (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, feature_id TEXT NOT NULL, state_code TEXT, lga_code TEXT, ward_code TEXT, resolution_status TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL DEFAULT 0, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(certification_version,feature_id)); CREATE INDEX IF NOT EXISTS idx_phase368_state ON gis_phase368_hierarchy_resolution(state_code); CREATE INDEX IF NOT EXISTS idx_phase368_lga ON gis_phase368_hierarchy_resolution(lga_code); CREATE INDEX IF NOT EXISTS idx_phase368_ward ON gis_phase368_hierarchy_resolution(ward_code);